using System; using System.Threading; using System.Threading.Tasks; using System.Net; using System.Net.Http; using System.Net.Http.Headers; using System.Web.Http; using AlKhayal.Api.Contracts; using AlKhayal.Application.Authentication;
namespace AlKhayal.Api.Controllers
{
    [RoutePrefix("api/auth")] public sealed class AuthController : ApiController
    {
        private const string CookieName = "alkhayal_session"; private readonly AuthService _auth; public AuthController(AuthService auth) { _auth=auth; }
        [HttpPost, Route("login")] public async Task<IHttpActionResult> Login(LoginRequest request, CancellationToken ct) { var result=await _auth.LoginAsync(request == null ? null : new LoginCommand { Username=request.Username, Password=request.Password }, ct); if(!result.Succeeded) { var status=result.ErrorCode=="validation"?HttpStatusCode.BadRequest:result.ErrorCode=="disabled_account"?HttpStatusCode.Forbidden:HttpStatusCode.Unauthorized; return Content(status, ApiEnvelope<object>.Fail(result.ErrorCode,result.ErrorMessage)); } var response=Request.CreateResponse(HttpStatusCode.OK,ApiEnvelope<UserResponse>.Ok(ToResponse(result.User,result.CsrfToken))); AddSessionCookie(response,result.SessionToken); return ResponseMessage(response); }
        [HttpGet, Route("me")] public async Task<IHttpActionResult> Me(CancellationToken ct) { var token=ReadToken(); var user=await _auth.GetCurrentUserAsync(token,ct); if(user==null) return Content(HttpStatusCode.Unauthorized,ApiEnvelope<object>.Fail("unauthorized","يرجى تسجيل الدخول أولاً.")); return Ok(ApiEnvelope<UserResponse>.Ok(ToResponse(user,await _auth.GetCsrfTokenAsync(token,ct)))); }
        [HttpPost, Route("logout")] public async Task<IHttpActionResult> Logout(CancellationToken ct) { var token=ReadToken(); if(!string.IsNullOrWhiteSpace(token) && !await _auth.ValidateCsrfAsync(token,ReadCsrfToken(),ct)) return Content(HttpStatusCode.Forbidden,ApiEnvelope<object>.Fail("invalid_csrf","تعذر التحقق من الطلب. حدّث الصفحة وحاول مرة أخرى.")); await _auth.LogoutAsync(token,ct); var response=Request.CreateResponse(HttpStatusCode.OK,ApiEnvelope<object>.Ok(new { loggedOut=true })); ExpireSessionCookie(response); return ResponseMessage(response); }
        private string ReadToken() { System.Collections.Generic.IEnumerable<string> values; if(!Request.Headers.TryGetValues("Cookie",out values)) return null; foreach(var header in values) foreach(var part in header.Split(';')) { var pair=part.Trim().Split(new[]{'='},2); if(pair.Length==2 && pair[0]==CookieName) return pair[1]; } return null; }
        private string ReadCsrfToken() { System.Collections.Generic.IEnumerable<string> values; return Request.Headers.TryGetValues("X-CSRF-Token",out values) ? System.Linq.Enumerable.FirstOrDefault(values) : null; }
        private void AddSessionCookie(System.Net.Http.HttpResponseMessage response,string token) { var suffix=Request.RequestUri.Scheme==Uri.UriSchemeHttps?"; Secure":""; response.Headers.Add("Set-Cookie",CookieName+"="+token+"; Path=/; HttpOnly; SameSite=Lax"+suffix); }
        private static void ExpireSessionCookie(HttpResponseMessage response) { response.Headers.Add("Set-Cookie",CookieName+"=; Path=/; Expires=Thu, 01 Jan 1970 00:00:00 GMT; HttpOnly; SameSite=Lax"); }
        private static UserResponse ToResponse(UserIdentity user,string csrfToken) { return new UserResponse { Id=user.Id, Username=user.Username, DisplayName=user.DisplayName, Role=user.Role, CsrfToken=csrfToken }; }
    }
}
